def Strongest_Extension(class_name, extensions):
    if not extensions:
        return class_name

    strongest_extension = extensions[0]
    for ext in extensions:
        cap_count, lowercase_count = 0, 0
        for char in ext:
            if char.isupper():
                cap_count += 1
            elif char.islower():
                lowercase_count += 1

        extension_strength = abs(cap_count - lowercase_count)
        if extension_strength > (ord(strongest_extension[0]) if strongest_extension else 0):
            strongest_extension = ext

    return f"{class_name}.{strongest_extension}"
```

