def by_length(arr):
    # Filter out numbers between 1 and 9, and sort them in reverse order
    valid_numbers = [num for num in arr if 1 <= num <= 9]
    valid_numbers_reversed = valid_numbers[::-1]

    # Define a dictionary to map numbers to their names
    number_names = {i: str(i).capitalize() for i in range(1, 10)}

    # If the array is empty, return an empty list
    if not arr:
        return []

    # If there are any invalid numbers in the array, handle them separately
    if len(arr) > len(valid_numbers):
        index = [i for i in arr if i not in range(1, 10)].index(next((i for i in arr if i not in range(1, 10)), None))
        return [number_names[len(str(arr[index]))]] + list(reversed(by_length(valid_numbers_reversed)))

    # Return the result of the function
    return list(reversed(by_length(valid_numbers_reversed)))
```

